/// <summary>
/// Extension of LogisticsAddressState Table
/// </summary>
[ExtensionOf(tableStr(LogisticsAddressState))]
final class METLogisticsAddressState_Extension
{
}

Method.Source:
/// <summary>
/// Decides whether the value of a specific field is valid.
/// </summary>
/// <param name="_fieldName">
/// The specified name of field to validate.
/// </param>
/// <param name="_arrayIndex">
/// THe specified array index for the field; optional.
/// </param>
/// <returns>
/// true if the validation passes; otherwise, false.
/// </returns>
/// <remarks>
/// Validates the <c>METStatePrefix</c> field.  Returns true if the field contains only digits; otherwise, displays an error message and returns false.
/// </remarks>
public boolean validateFieldValue(FieldName _fieldName, int _arrayIndex)
{
    boolean         ret;
    
    ret = next validateFieldValue(_fieldName, _arrayIndex);
    
    if (ret)
    {
        switch (_fieldName)
        {
            case fieldStr(LogisticsAddressState, METStatePrefix) :
                
                if (strlen(int2str(this.METStatePrefix)) > 1)
                {
                    ret = checkFailed("@MET:METStatePrefixValidation");
                }
                break;
        }
    }
    
    return ret;
}
